const MODULE_CONTENT = {"en":{"tax-basics":{"faq":[{"q":"Do I pay tax on shares I have not sold?","a":"No. Unrealised gains are not taxed until you sell or transfer the shares. But selling for rebalancing or to book profit does create a taxable event."},{"q":"Is intraday profit a capital gain?","a":"Generally no. Intraday equity profit is usually treated as speculative business income, taxed at your slab rate. Classification depends on your activity, so check your situation."},{"q":"Where do I find the numbers for my tax return?","a":"From your broker's profit and loss and capital gains statements, your contract notes, and the consolidated account statement from depositories and fund houses."}],"quiz":[{"q":"Shares held for 8 months and sold at a gain are generally:","o":["Short-term capital gain","Long-term capital gain","Business income","Tax-free"],"a":0,"e":"Listed equity held 12 months or less is short term. Verify current rates."},{"q":"Intraday equity losses can generally be set off against:","o":["Any income","Only speculative business income","Salary only","Nothing; they are never allowed"],"a":1,"e":"Speculative losses set off only against speculative income and carry forward for 4 years."},{"q":"Unrealised losses on a position you still hold:","o":["Reduce your tax now","Are always refunded","Do not reduce tax until realised","Count only for the broker"],"a":2,"e":"Only realised losses from actual sales are set off under the rules."},{"q":"Under the rules as understood, holding period decides capital gain category for listed equity by:","o":["Price","Lot size","Broker name","Whether held for more than 12 months"],"a":3,"e":"The 12-month line separates short and long term for listed equity."},{"q":"Intraday profit from shares is generally treated as:","o":["Speculative business income","Capital gain","Dividend income","Gift"],"a":0,"e":"Intraday equity is usually speculative business income taxed at the slab rate."},{"q":"F&O profits and losses are generally treated as:","o":["Capital gains","Non-speculative business income","Dividend","Exempt income"],"a":1,"e":"F&O is usually non-speculative business income for tax."},{"q":"Long-term capital losses can be set off against:","o":["Salary","Speculative income","Only long-term capital gains","Any income"],"a":2,"e":"Long-term losses offset only long-term gains."},{"q":"Capital losses can generally be carried forward for:","o":["1 year","4 years","Forever","8 years, if the return is filed on time"],"a":3,"e":"Capital losses carry forward for 8 years if the return is filed on time."},{"q":"Advance tax is generally required when estimated tax after TDS exceeds:","o":["₹10,000","₹1,000","₹1 lakh","₹50,000"],"a":0,"e":"Verify the current threshold on the official portal."},{"q":"Which record is most important for reporting trading income?","o":["A friend's note","Contract notes and broker profit and loss statements","A social media post","A newspaper clip"],"a":1,"e":"Official statements support the figures you report."},{"q":"Which return form is commonly used by traders with business income?","o":["ITR-1 only","No form needed","ITR-3, though check current instructions","ITR-7 only"],"a":2,"e":"Business income typically uses ITR-3; verify the form each year."},{"q":"Dividends from shares are generally taxed:","o":["At capital gains rates always","Never","At a fixed 1%","At the investor's slab rate"],"a":3,"e":"Dividends are added to income and taxed at the slab rate, subject to TDS rules."},{"q":"Rebalancing a portfolio by selling shares can:","o":["Create taxable gains when shares are sold","Never create tax","Reduce brokerage to zero","Hide gains"],"a":0,"e":"Selling realises gains, which can be taxable."},{"q":"Which is an example of grandfathering for shares bought before 31 January 2018?","o":["All gains are tax-free","Cost is the fair value on that date, under the rules","No tax is ever due","Losses are doubled"],"a":1,"e":"Grandfathering uses a specific cost basis; verify the rules before relying on it."},{"q":"Who should you consult before a complex tax position?","o":["A social media influencer","A random website","A qualified chartered accountant or tax professional","No one is needed"],"a":2,"e":"Complex positions need professional advice based on current law."},{"q":"Which source is the official place to verify current income tax rules?","o":["A broker's advertisement","A forum post","A friend's memory","incometax.gov.in and the latest Finance Act"],"a":3,"e":"The official portal and the Finance Act are the authoritative sources."},{"q":"Why keep records of every trade and the reason for it?","o":["To classify your activity correctly and file accurately","Only for fun","To avoid SEBI","Brokers require nothing"],"a":0,"e":"Records support classification and filing."},{"q":"Which mistake commonly causes higher tax?","o":["Selling just after 12 months when long-term rules apply","Selling shares shortly before the 12-month mark when gains are short-term","Keeping records","Filing on time"],"a":1,"e":"Timing a sale around the holding period can change the tax category."},{"q":"Not filing a return in a loss year can:","o":["Increase your refund","Reduce tax to zero","Lose the right to carry forward losses","Have no effect"],"a":2,"e":"Losses carry forward only if the return is filed on time."},{"q":"STT paid on trading is:","o":["A tax you can always reclaim fully","A dividend","A brokerage refund","A transaction tax, with treatment depending on the income category"],"a":3,"e":"STT treatment depends on the category; check with a professional."},{"q":"Before selling, a sensible tax check is to ask:","o":["How long have I held it, and which category does this sale fall into?","What colour is the chart?","Who is the broker's CEO?","Is it Monday?"],"a":0,"e":"Holding period and category decide the tax treatment."}]}},"hi":{"tax-basics":{"faq":[{"q":"क्या जो शेयर मैंने नहीं बेचे उन पर टैक्स लगता है?","a":"नहीं। अवास्तविक लाभ तब तक टैक्सेबल नहीं जब तक आप शेयर बेचें या ट्रांसफ़र करें। लेकिन रीबैलेंसिंग या लाभ बुक करने के लिए बेचने से टैक्सेबल घटना बनती है।"},{"q":"क्या इंट्राडे लाभ कैपिटल गेन है?","a":"आमतौर पर नहीं। इंट्राडे इक्विटी लाभ आमतौर पर स्पेक्युलेटिव बिज़नेस इनकम माना जाता है, जिस पर स्लैब दर लगती है। वर्गीकरण आपकी गतिविधि पर निर्भर है, इसलिए अपनी स्थिति जाँचें।"},{"q":"अपने टैक्स रिटर्न के आँकड़े कहाँ मिलेंगे?","a":"ब्रोकर के लाभ-हानि और कैपिटल गेन स्टेटमेंट, कॉन्ट्रैक्ट नोट, और डिपॉज़िटरी व फंड हाउस से कंसॉलिडेटेड अकाउंट स्टेटमेंट से।"}],"quiz":[{"q":"8 महीने रखे शेयर लाभ पर बेचे गए, वे आमतौर पर हैं:","o":["शॉर्ट-टर्म कैपिटल गेन","लॉन्ग-टर्म कैपिटल गेन","बिज़नेस इनकम","टैक्स-फ़्री"],"a":0,"e":"12 महीने या उससे कम रखे लिस्टेड इक्विटी शॉर्ट-टर्म होते हैं। मौजूदा दर जाँचें।"},{"q":"इंट्राडे इक्विटी नुकसान आमतौर पर किससे सेट-ऑफ़ हो सकता है?","o":["कोई भी आय","केवल स्पेक्युलेटिव बिज़नेस इनकम","केवल वेतन","कुछ नहीं; कभी अनुमति नहीं"],"a":1,"e":"स्पेक्युलेटिव नुकसान केवल स्पेक्युलेटिव आय से सेट-ऑफ़ होते हैं और 4 साल तक आगे जाते हैं।"},{"q":"आपके पास अभी मौजूद पोज़िशन पर अवास्तविक नुकसान:","o":["अभी टैक्स कम करते हैं","हमेशा रिफ़ंड होते हैं","वास्तविक होने तक टैक्स कम नहीं करते","केवल ब्रोकर के लिए गिने जाते हैं"],"a":2,"e":"नियमों के तहत केवल वास्तविक बिक्री से हुए नुकसान सेट-ऑफ़ होते हैं।"},{"q":"लिस्टेड इक्विटी के लिए होल्डिंग अवधि किससे श्रेणी तय करती है?","o":["कीमत से","लॉट साइज़ से","ब्रोकर के नाम से","क्या शेयर 12 महीने से ज़्यादा रखे गए"],"a":3,"e":"12 महीने की सीमा लिस्टेड इक्विटी को शॉर्ट और लॉन्ग टर्म में बाँटती है।"},{"q":"शेयरों से इंट्राडे लाभ आमतौर पर माना जाता है:","o":["स्पेक्युलेटिव बिज़नेस इनकम","कैपिटल गेन","डिविडेंड इनकम","उपहार"],"a":0,"e":"इंट्राडे इक्विटी आमतौर पर स्पेक्युलेटिव बिज़नेस इनकम है, जिस पर स्लैब दर लगती है।"},{"q":"F&O लाभ और नुकसान आमतौर पर माने जाते हैं:","o":["कैपिटल गेन","नॉन-स्पेक्युलेटिव बिज़नेस इनकम","डिविडेंड","छूट प्राप्त आय"],"a":1,"e":"टैक्स के लिए F&O आमतौर पर नॉन-स्पेक्युलेटिव बिज़नेस इनकम है।"},{"q":"लॉन्ग-टर्म कैपिटल लॉस किससे सेट-ऑफ़ हो सकता है?","o":["वेतन से","स्पेक्युलेटिव आय से","केवल लॉन्ग-टर्म कैपिटल गेन से","कोई भी आय से"],"a":2,"e":"लॉन्ग-टर्म नुकसान केवल लॉन्ग-टर्म लाभ से सेट-ऑफ़ होते हैं।"},{"q":"कैपिटल लॉस आमतौर पर कितने समय तक आगे ले जाए जा सकते हैं?","o":["1 साल","4 साल","हमेशा","8 साल, अगर रिटर्न समय पर भरा गया हो"],"a":3,"e":"समय पर रिटर्न भरने पर कैपिटल लॉस 8 साल तक आगे जाते हैं।"},{"q":"एडवांस टैक्स आमतौर पर तब ज़रूरी है जब TDS के बाद अनुमानित टैक्स इससे ज़्यादा हो:","o":["₹10,000","₹1,000","₹1 लाख","₹50,000"],"a":0,"e":"मौजूदा सीमा आधिकारिक पोर्टल पर जाँचें।"},{"q":"ट्रेडिंग आय रिपोर्ट करने के लिए सबसे महत्वपूर्ण रिकॉर्ड कौन सा है?","o":["किसी दोस्त का नोट","कॉन्ट्रैक्ट नोट और ब्रोकर का लाभ-हानि स्टेटमेंट","सोशल मीडिया पोस्ट","अख़बार की कतरन"],"a":1,"e":"आधिकारिक स्टेटमेंट रिपोर्ट किए आँकड़ों का समर्थन करते हैं।"},{"q":"बिज़नेस इनकम वाले ट्रेडर आमतौर पर कौन सा रिटर्न फ़ॉर्म भरते हैं?","o":["केवल ITR-1","कोई फ़ॉर्म नहीं","ITR-3, पर मौजूदा निर्देश जाँचें","केवल ITR-7"],"a":2,"e":"बिज़नेस इनकम के लिए आमतौर पर ITR-3; हर साल फ़ॉर्म जाँचें।"},{"q":"शेयरों के डिविडेंड पर आमतौर पर टैक्स लगता है:","o":["हमेशा कैपिटल गेन दर पर","कभी नहीं","स्थिर 1% पर","निवेशक की स्लैब दर पर"],"a":3,"e":"डिविडेंड आय में जुड़कर स्लैब दर पर टैक्स होता है, TDS नियमों के अधीन।"},{"q":"बिक्री से पोर्टफ़ोलियो रीबैलेंस करने पर:","o":["शेयर बेचने पर टैक्सेबल लाभ बन सकता है","कभी टैक्स नहीं बनता","ब्रोकरेज शून्य हो जाती है","लाभ छिप जाता है"],"a":0,"e":"बिक्री से लाभ वास्तविक होता है, जो टैक्सेबल हो सकता है।"},{"q":"31 जनवरी 2018 से पहले ख़रीदे शेयरों के लिए ग्रैंडफ़ादरिंग का उदाहरण कौन सा है?","o":["सारे लाभ टैक्स-फ़्री","उस तारीख़ का उचित मूल्य लागत माना जा सकता है, नियमों के तहत","कभी टैक्स नहीं","नुकसान दोगुने"],"a":1,"e":"ग्रैंडफ़ादरिंग एक विशेष लागत आधार देती है; भरोसे से पहले नियम जाँचें।"},{"q":"जटिल टैक्स स्थिति से पहले किससे सलाह लें?","o":["किसी सोशल मीडिया इन्फ़्लुएंसर से","किसी यादृच्छिक वेबसाइट से","योग्य चार्टर्ड अकाउंटेंट या टैक्स पेशेवर से","किसी की ज़रूरत नहीं"],"a":2,"e":"जटिल स्थितियों में मौजूदा कानून के आधार पर पेशेवर सलाह चाहिए।"},{"q":"मौजूदा आयकर नियम जाँचने का आधिकारिक स्रोत कौन सा है?","o":["ब्रोकर का विज्ञापन","फ़ोरम पोस्ट","किसी दोस्त की याददाश्त","incometax.gov.in और नवीनतम फ़ाइनेंस एक्ट"],"a":3,"e":"आधिकारिक पोर्टल और फ़ाइनेंस एक्ट प्रामाणिक स्रोत हैं।"},{"q":"हर ट्रेड और उसका कारण रिकॉर्ड करना क्यों ज़रूरी है?","o":["आपकी गतिविधि सही वर्गीकृत करने और सही फ़ाइलिंग के लिए","केवल मनोरंजन के लिए","SEBI से बचने के लिए","ब्रोकर कुछ नहीं माँगते"],"a":0,"e":"रिकॉर्ड वर्गीकरण और फ़ाइलिंग का समर्थन करते हैं।"},{"q":"कौन सी गलती अक्सर ज़्यादा टैक्स का कारण बनती है?","o":["लॉन्ग-टर्म नियम लागू होने पर 12 महीने पूरे होने के बाद बेचना","12 महीने की सीमा से ठीक पहले बेचना, जब लाभ शॉर्ट-टर्म हो","रिकॉर्ड रखना","समय पर फ़ाइल करना"],"a":1,"e":"होल्डिंग अवधि के आसपास बिक्री का समय टैक्स श्रेणी बदल सकता है।"},{"q":"नुकसान वाले वर्ष में रिटर्न न भरने से:","o":["रिफ़ंड बढ़ता है","टैक्स शून्य हो जाता है","नुकसान आगे ले जाने का अधिकार खो जाता है","कोई असर नहीं"],"a":2,"e":"नुकसान तभी आगे जाते हैं जब रिटर्न समय पर भरा गया हो।"},{"q":"ट्रेडिंग पर दिया गया STT है:","o":["ऐसा टैक्स जिसे आप हमेशा पूरा वापस ले सकते हैं","डिविडेंड","ब्रोकरेज रिफ़ंड","लेनदेन टैक्स, जिसका व्यवहार आय श्रेणी पर निर्भर है"],"a":3,"e":"STT का व्यवहार श्रेणी पर निर्भर है; किसी पेशेवर से जाँचें।"},{"q":"बिक्री से पहले एक सही टैक्स जाँच है पूछना:","o":["मैंने इसे कितने समय से रखा है, और यह बिक्री किस श्रेणी में आती है?","चार्ट का रंग क्या है?","ब्रोकर का CEO कौन है?","क्या आज सोमवार है?"],"a":0,"e":"होल्डिंग अवधि और श्रेणी टैक्स व्यवहार तय करते हैं।"}]}}};
