const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Dividend","hi":"डिविडेंड (लाभांश)"},"def":{"en":"A share of profit a company pays to its shareholders, usually per share.","hi":"कंपनी द्वारा शेयरधारकों को दिया जाने वाला मुनाफ़े का हिस्सा, आमतौर पर प्रति शेयर।"}},{"cat":"basics","term":{"en":"Compounding","hi":"कंपाउंडिंग (चक्रवृद्धि)"},"def":{"en":"Returns that earn their own returns over time, so growth accelerates.","hi":"ऐसा रिटर्न जो समय के साथ अपना भी रिटर्न कमाता है, इसलिए वृद्धि तेज़ होती है।"}},{"cat":"trading","term":{"en":"Intraday","hi":"इंट्राडे"},"def":{"en":"Trades opened and closed within the same trading session. Positions must be squared off before the market closes.","hi":"एक ही ट्रेडिंग सत्र में खुले और बंद होने वाले ट्रेड। बाज़ार बंद होने से पहले पोज़िशन बंद करनी होती है।"}},{"cat":"trading","term":{"en":"Swing trading","hi":"स्विंग ट्रेडिंग"},"def":{"en":"Holding trades for days to weeks to capture a price swing.","hi":"कीमत की एक चाल पकड़ने के लिए ट्रेड को कुछ दिनों से हफ़्तों तक रखना।"}},{"cat":"trading","term":{"en":"Brokerage","hi":"ब्रोकरेज"},"def":{"en":"The fee a broker charges for executing a trade.","hi":"ट्रेड पूरा करने के लिए ब्रोकर द्वारा लिया जाने वाला शुल्क।"}},{"cat":"india","term":{"en":"STT (Securities Transaction Tax)","hi":"STT (सिक्योरिटीज़ ट्रांज़ैक्शन टैक्स)"},"def":{"en":"A tax charged by the government on securities transactions, varying by trade type.","hi":"प्रतिभूति लेनदेन पर सरकार द्वारा लगाया जाने वाला टैक्स, जो ट्रेड के प्रकार के अनुसार बदलता है।"}},{"cat":"basics","term":{"en":"Emergency fund","hi":"इमरजेंसी फ़ंड"},"def":{"en":"Cash or very safe, liquid savings to cover 3 to 6 months of expenses. Keep it separate from investments.","hi":"3 से 6 महीने के खर्च के लिए नकद या बहुत सुरक्षित, तुरंत उपलब्ध बचत। इसे निवेश से अलग रखें।"}}];
